import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import examService from '../../api/services/examService';
import { useNotification } from '../../context/notification/NotificationContext';
import Card from '../../components/ui/Card';
import Button from '../../components/ui/Button';
import LoadingSpinner from '../../components/ui/LoadingSpinner';

const ExamSessionList = () => {
  const navigate = useNavigate();
  const { showNotification } = useNotification();
  const [sessions, setSessions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    loadSessions();
  }, []);

  const loadSessions = async () => {
    try {
      setIsLoading(true);
      // This would call your exam service to get sessions
      // For now, showing example structure
      const response = await examService.getExamSessions();
      setSessions(response.data || []);
    } catch (error) {
      showNotification({
        type: 'error',
        message: 'Failed to load exam sessions',
        duration: 5000
      });
      // Mock data for demo
      setSessions([
        {
          id: '1',
          name: 'Mathematics Final Exam',
          description: 'Final examination for Mathematics course',
          start_time: new Date().toISOString(),
          end_time: new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString(),
          is_active: true
        },
        {
          id: '2',
          name: 'Physics Midterm',
          description: 'Midterm examination for Physics',
          start_time: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(),
          end_time: new Date(Date.now() - 22 * 60 * 60 * 1000).toISOString(),
          is_active: false
        }
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  const startMonitoring = (sessionId) => {
    navigate(`/teacher/monitoring/${sessionId}`);
  };

  const formatDateTime = (dateString) => {
    const date = new Date(dateString);
    return date.toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const isSessionActive = (session) => {
    const now = new Date();
    const start = new Date(session.start_time);
    const end = new Date(session.end_time);
    return now >= start && now <= end;
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <LoadingSpinner size="lg" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">
            Exam Sessions
          </h1>
          <p className="text-gray-600 dark:text-gray-400 mt-1">
            Manage and monitor your exam sessions
          </p>
        </div>
        <Button onClick={loadSessions} variant="secondary">
          <svg
            className="w-4 h-4 mr-2"
            fill="none"
            stroke="currentColor"
            viewBox="0 0 24 24"
          >
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth={2}
              d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
            />
          </svg>
          Refresh
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {sessions.map((session) => {
          const isActive = isSessionActive(session);
          
          return (
            <Card key={session.id}>
              <div className="p-6">
                <div className="flex items-start justify-between mb-4">
                  <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
                    {session.name}
                  </h3>
                  {isActive && (
                    <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200">
                      <span className="w-2 h-2 mr-1 bg-green-400 rounded-full animate-pulse"></span>
                      Active
                    </span>
                  )}
                </div>

                {session.description && (
                  <p className="text-sm text-gray-600 dark:text-gray-400 mb-4">
                    {session.description}
                  </p>
                )}

                <div className="space-y-2 mb-4 text-sm">
                  <div className="flex items-center text-gray-600 dark:text-gray-400">
                    <svg
                      className="w-4 h-4 mr-2"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                    Start: {formatDateTime(session.start_time)}
                  </div>
                  <div className="flex items-center text-gray-600 dark:text-gray-400">
                    <svg
                      className="w-4 h-4 mr-2"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"
                      />
                    </svg>
                    End: {formatDateTime(session.end_time)}
                  </div>
                </div>

                <div className="flex gap-2">
                  <Button
                    onClick={() => startMonitoring(session.id)}
                    className={`flex-1 ${
                      isActive
                        ? 'bg-blue-600 hover:bg-blue-700'
                        : 'bg-gray-600 hover:bg-gray-700'
                    }`}
                  >
                    <svg
                      className="w-4 h-4 mr-2"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M15 10l4.553-2.276A1 1 0 0121 8.618v6.764a1 1 0 01-1.447.894L15 14M5 18h8a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v8a2 2 0 002 2z"
                      />
                    </svg>
                    {isActive ? 'Monitor Now' : 'View Recording'}
                  </Button>
                  <Button
                    variant="secondary"
                    onClick={() => navigate(`/teacher/session/${session.id}`)}
                  >
                    Details
                  </Button>
                </div>
              </div>
            </Card>
          );
        })}
      </div>

      {sessions.length === 0 && (
        <Card>
          <div className="p-12 text-center">
            <svg
              className="w-16 h-16 mx-auto mb-4 text-gray-400"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
              />
            </svg>
            <h3 className="text-lg font-medium text-gray-900 dark:text-white mb-2">
              No Exam Sessions
            </h3>
            <p className="text-gray-600 dark:text-gray-400 mb-4">
              You don't have any exam sessions yet. Create one to start monitoring.
            </p>
            <Button onClick={() => navigate('/teacher/dashboard')}>
              Go to Dashboard
            </Button>
          </div>
        </Card>
      )}
    </div>
  );
};

export default ExamSessionList;
